import attr
import pytest

@attr.s(frozen=True)
class MyException(Exception):
    message: attr.ib()

def test_frozen_exception_context_suppression():
    exc = MyException(message="Error")
    try:
        exc.__suppress_context__ = True
    except attr.exceptions.FrozenInstanceError:
        pytest.fail("Failed to set __suppress_context__ on frozen exception")
    assert exc.__suppress_context__ is True

def test_frozen_exception_notes():
    exc = MyException(message="Error")
    try:
        exc.add_note("Note 1")
    except attr.exceptions.FrozenInstanceError:
        pytest.fail("Failed to add note to frozen exception")
    # __notes__ is a tuple, let's see if it's actually set
    assert "__notes__" in exc.__dict__ or hasattr(exc, "__notes__")

if __name__ == "__main__":
    test_frozen_exception_context_suppression()
    # add_note might not be available in all Python versions, but let's try
    try:
        test_frozen_exception_notes()
    except AttributeError:
        print("add_note not supported in this Python version")
    print("All tests passed!")

import attr
import pytest

@attr.s(frozen=True)
class MyException(Exception):
    message: attr.ib()

def test_frozen_exception_context_suppression():
    exc = MyException("Error")
    try:
        exc.__suppress_context__ = True
    except attr.exceptions.FrozenInstanceError:
        pytest.fail("Failed to set __suppress_context__ on frozen exception")
    assert exc.__suppress_context__ is True

def test_frozen_exception_notes():
    exc = MyException("Error")
    try:
        exc.__notes__ = ("Note 1",)
    except attr.exceptions.FrozenInstanceError:
        pytest.fail("Failed to set __notes__ on frozen exception")
    assert exc.__notes__ == ("Note 1",)

if __name__ == "__main__":
    test_frozen_exception_context_suppression()
    test_frozen_exception_notes()
    print("All tests passed!")

